begin;
create temporary table review_decisions(id uuid,status text,url text,kind text,reason text,parent_id uuid) on commit drop;
do $$ begin if (select count(*) from discovered_links d join review_decisions r using(id) where d.status='pending') <> 207 then raise exception 'Discovery queue changed; re-review before applying'; end if; end $$;
update discovered_links d set status=r.status from review_decisions r where d.id=r.id and d.status='pending';
select d.status,count(*) from discovered_links d join review_decisions r using(id) group by d.status order by d.status;
commit;
